//trafficService.js
import axios from 'axios';

const API_KEY = 'FlH0A2gFpIPtzwGydKy54qRCATz4t9KI-eMBATe5Vrg'; // Remplacez par votre clé API

export const getTrafficData = async (bounds) => {
  try {
    const response = await axios.get(`https://traffic.api.here.com/traffic/6.3/flow.json`, {
      params: {
        app_id: API_KEY,
        bbox: `${bounds.getSouth()},${bounds.getWest()};${bounds.getNorth()},${bounds.getEast()}`
      }
    });
    return response.data;
  } catch (error) {
    console.error('Erreur lors de la récupération des données de trafic', error);
    return null;
  }
};
